void RaceCarEntityModule::Construct()
{
    mePrepareStage             = 0;
    miPrepareCarIndex          = 0;
    meLoadGlobalResourcesStage = 0;
    miExpectedResponseCount    = 0;

    mReceiverQueue.Construct();

    // X360 Construct @0x822FD8F8..0x822FD914 initializes the embedded Boost page:
    // the base Construct is the folded empty body, followed by the owner pointer,
    // miBoostRules = 1, and miActionTextModifiedTime = 0.
    mBoostDebugComponent.Construct(this);

    // X360: the module Construct brings the streamer up along with the rest of the
    // interior (the receiver queue and the streamer are adjacent members, +0x100E8 and
    // +0x11100). Without this the five component streamers have no request/receiver
    // queues, so no AddEntry can ever reach a request ring.
    // ARTIST 822FD924: Construct the embedded diagnostic owner before the streamer.
    mRCEntityModuleDebugComponent.Construct(this);
    mRaceCarStreamer.Construct();
    mfTimeStep = 0.0f;
    mfLastPlayerCarSpeed = 0.0f;
    mbOncomingTimerActive = false;
    mfOncomingNoClueTimer = 0.0f;
    mfTimeStepMultiplier = 0.0f;   // the console's Construct seeds this seat from the same 0.0f

    // The crash-play manager is a by-value member and ARTIST inlines its Construct here. Landing
    // it stops the console's own `mpCrashPlayManager != NULL` assert (BrnCrashPlayDebugComponent
    // .cpp:111) firing once per Update frame -- 7,050 times in a single 150 s run before this.
    mCrashPlayManager.Construct();

    // The power-parking manager is the next by-value member (+0x18250) and ARTIST inlines its
    // Construct right after the crash-play block: 0x822FDADC r10 = module + 0x18250, 0x822FDB14
    // `stb r31(=0), 0x94(r10)` and 0x822FDB1C `stw r10, 0x90(r10)` (crash parity FX-SCENEMGR
    // item 4). Without the back pointer the component's own `mpPowerParkingManager != NULL`
    // tripwire fires on every PowerParkingManager::Update.
    mPowerParkingManager.Construct();

    // [FLAG PC bring-up] mCameraTransform is seeded to IDENTITY rather than left as whatever the
    // module's raw storage holds. The console never seeds it here -- PreSceneUpdate step 2 latches
    // it every frame from InputBuffer_PreScene::GetCam...() -- but that latch cannot be
    // reproduced yet: the source is a BrnDirector::Camera::Camera whose layout is not
    // reconstructed (the IO header only forward-declares it), so there is nothing to copy FROM.
    // Identity is not a behaviour guess, it is the value that keeps the CONSOLE'S OWN asserts
    // quiet: CrashPlayManager::Update asserts MagnitudeSquared(lCameraX) > 0 and
    // MagnitudeSquared(lCameraZ) > 0 every frame, and on this build an assert BLOCKS. The only
    // consumer downstream of those two axes is the traffic-stomp air-ram direction, which is
    // itself unreachable until OnCarCrash lands and sets mbTrafficStomp -- so the deviation is
    // confined to code nothing can currently execute.
    // DELETE-WHEN BrnDirector::Camera::Camera has a layout and PreSceneUpdate step 2 lands.
    mCameraTransform.SetIdentity();

    // X360 0x822FD898: the two per-slot Construct sweeps, `ActiveRaceCar::Construct(i)`
    // x8 (asm 0x822FDBxx) and `RaceCar::Construct(i)` x35. Both arrays are real members
    // now, so both sweeps are restored (pose wave 2026-07-31). ActiveRaceCar::Construct
    // is what stores meActiveRaceCarIndex, which Attach then uses for the car's
    // handling-body VolumeInstanceId, and RaceCar::Construct is what sets
    // miGlobalRaceCarIndex -- AddToWorld asserts on it ("Using unprepared RaceCar").
    for( s32 liActive = 0; liActive < E_ACTIVE_RACE_CAR_INDEX_COUNT; ++liActive )
    {
        maActiveRaceCars[liActive].Construct( static_cast<EActiveRaceCarIndex>( liActive ) );
    }
    for( s32 liGlobal = 0; liGlobal < E_GLOBAL_RACE_CAR_INDEX_COUNT; ++liGlobal )
    {
        maRaceCars[liGlobal].Construct( static_cast<EGlobalRaceCarIndex>( liGlobal ) );
    }

    // ⭐⭐⭐ 0x822FDB20 `stwx r29, r30, r9` with r9 == 0x18368 and r29 == -1 (`li r29, -1`
    // @0x822FDA58, not touched again before the store) -- the console SEEDS meGameModeType to
    // E_MODE_NONE here. This tree did not, so on a fresh boot the member held the module pool's
    // zero, which is E_MODE_OFFLINE_RACE (0), and NOTHING sets it back: the only other writers are
    // ArmGameMode (a mode START) and HandleStopModeAction (a mode STOP), neither of which ever
    // runs in free burn.
    // WHY IT MATTERS, and it is issue #28's other half: ActiveRaceCar::Update @0x822F7A18 branches
    // the crash drive-away decision on exactly this value -- `cmpwi r11, 0 ; beq` / `cmpwi r11, 5 ;
    // beq` select the PLAYER ROUTE-DIRECTION test (modes 0 OFFLINE_RACE and 5 BURNING_ROUTE, the
    // two route-following modes) instead of free burn's plain `if (!mbIsWrecked) canDriveAway`.
    // So every free-burn player crash was being judged against a racing line that does not exist,
    // and whenever dot(carDirection, routeDirection) came out negative the console's own
    // `stb r30, 0x782` @0x822F7BFC latched mbIsWrecked on a car that was upright, undented and
    // fully drivable. MEASURED (run i28_afterB, BRN_WRECK_LATCH_DIAG=1):
    //   [wrecklatch] car=0 <- 1 site=Update.routeDot@0x822F7BFC
    //   [crash-verdict] ... IsWrecked=1 isDriveable=1 fullyDrivable=1 upDot=0.999441
    mbIsInGameMode            = false;
    meGameModeType            = BrnGameState::GameStateModuleIO::E_MODE_NONE;   // stwx -1, +0x18368
    mbIsInOnlineGameMode      = false;
    mbOnlineModeJustFinished  = false;
    mbWaitingForStreaming    = false;
    mbSendStreamingComplete  = false;
    mbCarSelectAllowedInGameMode = false;
    // X360 Construct @0x822FDBA4 / @0x822FDBAC seeds +0x1834A to 0 and +0x18349 to 1.
    mbRivalDebug = false;
    mbDisplayPlayerCarPosition = true;
    mbInCarSelectScreen       = false;
    mbInCarModScreen          = false;
    meCarSelectResetType      = 0;     // E_CAR_SELECT_DONT_DROP
    mbCarSelectDontStreamAudio = false;
    mbHACK_ExitingCarSelectWaitForAudio = false;   // stbx r31 (0), +0x186D1 @0x822FDBC0

    // Crash parity G61-D4: the inlined Random::Construct on module +0x18490 (`addis r11, r30, 2 ;
    // addi r11, r11, -0x7B70` @0x822FDD34/0x822FDD60; the default seed 0xC87CD8C91AD0891B built at
    // 0x822FDCA0/0x822FDC18, the ring primed through 0x822FE024).
    mNonDeterministicRandom.Construct();

    mpVehicleList        = 0;
    mpWheelList          = 0;
    mbCarColoursBound    = false;

    // ⭐ 0x822FE274..0x822FE2AC -- the base-deformation mirror block. These five seats were NAMED
    // in this header but NEVER SEEDED here, so on the host they started as whatever the module's
    // pool storage happened to hold, while the console writes all five explicitly in Construct.
    // That matters now that ResetActiveRaceCar actually READS the live pair (it used to pass a
    // hard -1/0.0f, which accidentally matched these initialisers and hid the omission).
    //   0x822FE284  stwx  -1   -> +0x184D0    0x822FE274  stfsx 0.0f -> +0x184D8
    //   0x822FE2A4  stwx  -1   -> +0x184D4    0x822FE2A8  stfsx 0.0f -> +0x184E0
    //   0x822FE2AC  stbx  r30(=0) -> +0x184DC
    miPlayerBaseDeformationTypeMirror = -1;
    mfPlayerBaseDeformAmountMirror    = 0.0f;
    miPlayerBaseDeformationTypeSaved  = -1;
    mfPlayerBaseDeformAmountSaved     = 0.0f;
    mbPlayerBaseDeformRequestPending  = false;

    // ⭐ crash parity 2026-09-23 (G61-D2 / G68-D5) -- two more seeds this slice had skipped.
    //   0x822FE034  stfsx f0 (flt_82004F68 == 0x3FE00000 == 1.75f), this, 0x184CC
    //               -> mfResetOnWaterHeight. The only game reader is CheckForResetOnTrackConditions
    //               (the water / super-fatal surface test's slack); unseeded it read the module
    //               pool's 0.0f, i.e. a car counted as ON the water only when its lowest point was
    //               at or below the surface, where the console allows 1.75 m.
    //   0x822FE2B0  stfsx f30 (flt_820037C8 == -1.0f), this, 0x1839C -> mfIntroTimer, "not
    //               counting" until HandleGameActions case 29 arms it.
    mfResetOnWaterHeight = 1.75f;   // flt_82004F68
    mfIntroTimer         = -1.0f;   // flt_820037C8

    // The three render switches the dispatch leg reads (see the header for the offset
    // fit). The console seeds them from its debug-variable table, which is not live on
    // this build; body, coronas and wheels all default ON.
    mbRenderCarsDuringCrash = true;
    mbRenderRaceCarCoronas  = true;

    // ON since the wheel-render wave (2026-08-03). RenderRaceCar's wheel block is now
    // reconstructed, Model::SetupShaderConstantsForInstancing has a body, and the
    // instanced submission is unrolled into per-instance mesh commands in
    // DrawRenderable::Interpret, so no draw ever reaches the
    // DrawInstancedIndexedPrimitive_Custom trap.
    mbRenderWheels = true;
}

